"""R09 migration: checkpoints generated by the CURRENT production path."""
import copy
import importlib
import json
from pathlib import Path
import shutil
import sys
import pytest

ROOT=Path(__file__).resolve().parents[1]
sys.path[:0]=[str(ROOT),str(ROOT/'src')]

@pytest.fixture(scope='module')
def isolated(tmp_path_factory):
    root=tmp_path_factory.mktemp('p2a_current_dependency_root')
    for name in ('src','configs','inputs'):
        shutil.copytree(ROOT/name,root/name,ignore=shutil.ignore_patterns('__pycache__'))
    for p in [*ROOT.glob('*.py'),*ROOT.glob('requirements*.txt')]:shutil.copy2(p,root/p.name)
    return root

def arguments(root,out):
    return dict(out=out,root=root,steps=3,risk_horizon=1,seed=17,
        execution_contract=json.loads((root/'configs/p1b_execution_research.json').read_text()),
        scenario_specs=[dict(id='p2_manifest_a',stage=2,start_hour=4300,duration_steps=3,
                            shock={'e':.1},family_id='family_a',parent_template_id='parent_a')])

@pytest.fixture(scope='module')
def checkpoint(isolated,tmp_path_factory):
    from generate_nonmpc_training import run
    out=tmp_path_factory.mktemp('p2a_current_checkpoint')
    args=arguments(isolated,out)
    # Failure before implementation is intentional: old generator lacks full manifest API.
    result=run(**args)
    assert result['trajectories']==2 and result['steps']==6
    return args

@pytest.mark.parametrize('relative',[
    'src/hospital_ies/model.py','configs/plant_configs.json',
    'configs/p1b_execution_research.json','inputs/loads/hospital_ies_demand_8760.csv',
    'src/hospital_ies/training_schema.py'])
def test_current_checkpoint_rejects_each_dependency_byte_change(checkpoint,relative):
    from generate_nonmpc_training import run
    p=checkpoint['root']/relative;original=p.read_bytes()
    try:
        p.write_bytes(original+b'\n')
        with pytest.raises(ValueError,match='fingerprint|manifest|dependency'):
            run(**dict(checkpoint,resume=True))
    finally:p.write_bytes(original)

@pytest.mark.parametrize('key',['feature','label'])
def test_semantic_versions_alone_reject_resume(checkpoint,key):
    from generate_nonmpc_training import run
    from hospital_ies.data_contract import SCHEMA_VERSIONS
    versions=dict(SCHEMA_VERSIONS);versions[key]+='.changed'
    with pytest.raises(ValueError,match='fingerprint|manifest|dependency'):
        run(**dict(checkpoint,resume=True,schema_versions=versions))

def test_unchanged_resume_and_checkpoint_integrity(checkpoint):
    from generate_nonmpc_training import run
    assert run(**dict(checkpoint,resume=True))['steps']==6
    cp=next((checkpoint['out']/'checkpoints_p2a').glob('*.json'))
    old=cp.read_bytes()
    try:
        cp.write_bytes(old+b' ')
        with pytest.raises(ValueError,match='checkpoint'):run(**dict(checkpoint,resume=True))
    finally:cp.write_bytes(old)

def test_batch_and_reverse_order_reproduce_same_data(isolated,tmp_path):
    from generate_nonmpc_training import run
    from hospital_ies.dataset_manifest import canonical_payload
    args=arguments(isolated,tmp_path/'one')
    args['scenario_specs']+=[dict(args['scenario_specs'][0],id='p2_manifest_b',start_hour=4305,
                                family_id='family_b',parent_template_id='parent_b')]
    run(**args)
    batch=dict(args,out=tmp_path/'batch',scenario_specs=list(reversed(args['scenario_specs'])),
               policies=('secure_milp','priority_milp'))
    first=run(**dict(batch,max_trajectories=1))
    assert first['attempted']==1 and first['planned_trajectories']==4
    run(**dict(batch,resume=True))
    for cp in (args['out']/'checkpoints_p2a').glob('*.json'):
        a=json.loads(cp.read_text());b=json.loads((batch['out']/'checkpoints_p2a'/cp.name).read_text())
        assert canonical_payload(a)==canonical_payload(b)

def test_manifest_inventory_covers_transitive_production_and_all_inputs(checkpoint):
    m=json.loads((checkpoint['out']/'manifest_p2a.json').read_text())
    names={x['path'] for x in m['files']}
    for p in (checkpoint['root']/'src').rglob('*.py'):assert p.relative_to(checkpoint['root']).as_posix() in names
    for p in (checkpoint['root']/'inputs').rglob('*'):
        if p.is_file():assert p.relative_to(checkpoint['root']).as_posix() in names
    assert m['schemas']['feature'] and m['schemas']['label']
    assert m['execution_contract']['name'] and m['scenarios'] and m['runtime']['packages']['scipy']

def test_new_manifest_cannot_claim_unexecuted_different_source(isolated,tmp_path):
    from generate_nonmpc_training import run
    p=isolated/'src/hospital_ies/control_env.py';old=p.read_bytes()
    try:
        p.write_bytes(old+b'\n# altered implementation not imported\n')
        with pytest.raises(ValueError,match='source|dependency|fingerprint'):
            run(**arguments(isolated,tmp_path/'false_source'))
    finally:p.write_bytes(old)

def test_refuse_unowned_nonempty_output_directory(isolated,tmp_path):
    from generate_nonmpc_training import run
    p=tmp_path/'closed_loop_expert_steps.csv';p.write_text('immutable historical artifact',encoding='utf-8')
    with pytest.raises((ValueError,FileExistsError),match='output|directory|Existing'):
        run(**arguments(isolated,tmp_path))
    assert p.read_text(encoding='utf-8')=='immutable historical artifact'
